import{_ as e,c as l,a2 as t,o as r}from"./chunks/framework.BnrAgU0Y.js";const a="/bllm/assets/8f00cc95e7b03346d7e9d19f7ceb08f0.CyL91fDR.gif",g="/bllm/assets/04294fbc49c30b178f29c1be5ff9dd7d.DHnElSWI.gif",f=JSON.parse('{"title":"集成 Google OAuth 到 Langflow","description":"集成 Google OAuth 到 Langflow","frontmatter":{"title":"集成 Google OAuth 到 Langflow","description":"集成 Google OAuth 到 Langflow","layout":"doc"},"headers":[],"relativePath":"langflow/integrations-setup-google-oauth-langflow.md","filePath":"langflow/integrations-setup-google-oauth-langflow.md"}'),n={name:"langflow/integrations-setup-google-oauth-langflow.md"};function s(i,o,c,d,h,u){return r(),l("div",null,o[0]||(o[0]=[t('<h1 id="集成-google-oauth-到-langflow" tabindex="-1">集成 Google OAuth 到 Langflow <a class="header-anchor" href="#集成-google-oauth-到-langflow" aria-label="Permalink to &quot;集成 Google OAuth 到 Langflow&quot;">​</a></h1><p>Langflow 集成了 <a href="https://developers.google.com/identity/protocols/oauth2" target="_blank" rel="noreferrer">Google OAuth</a> 来验证 <a href="/bllm/components-data.html#gmail-loader">Gmail 加载器</a>、<a href="/bllm/components-data.html#google-drive-loader">Google Drive 加载器</a> 和 <a href="/bllm/components-data.html#google-drive-search">Google Drive 搜索</a> 组件。</p><p>了解如何在 Google Cloud 中创建一个 OAuth 应用，获取必要的凭证和访问令牌，并将它们添加到 Langflow 的 Google 组件中。</p><h2 id="创建-google-cloud-的-oauth-应用" tabindex="-1">创建 Google Cloud 的 OAuth 应用 <a class="header-anchor" href="#创建-google-cloud-的-oauth-应用" aria-label="Permalink to &quot;创建 Google Cloud 的 OAuth 应用&quot;">​</a></h2><ol><li>访问 <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud 控制台</a>.</li><li>点击 <strong>Select a project</strong>，然后点击 <strong>New Project</strong> 以创建一个新项目。</li></ol><p><img src="'+a+'" alt="OAuth Client ID and Secret"></p><ol start="3"><li>要为项目启用 API，请选择 <strong>APIs &amp; Services</strong>，然后点击 <strong>Library</strong>。启用项目所需的 API。例如，如果您的流程使用了 Google Drive 组件，则启用 Google Drive API。</li><li>要导航到 OAuth 同意屏幕，请点击 <strong>APIs &amp; Services</strong>，然后点击 <strong>OAuth consent screen</strong>。</li><li>在您的 OAuth 同意屏幕上填写应用名称、用户支持电子邮件、所需的 <a href="https://developers.google.com/identity/protocols/oauth2/scopes" target="_blank" rel="noreferrer">范围(scopes)</a> 以及授权域名。</li><li>要创建 <strong>OAuth Client ID</strong>，导航到 <strong>Clients</strong>，然后点击 <strong>Create Client</strong>。</li><li>选择 <strong>Desktop app</strong> 作为应用类型，然后为您的 client ID 命名。</li><li>点击 <strong>Create</strong>。Client ID 和 Client Secret 将被创建。将凭证下载为 JSON 文件到您的本地机器并妥善保存。</li></ol><p><img src="'+g+'" alt="OAuth Client ID and Secret"></p><hr><h2 id="获取访问令牌和刷新令牌" tabindex="-1">获取访问令牌和刷新令牌 <a class="header-anchor" href="#获取访问令牌和刷新令牌" aria-label="Permalink to &quot;获取访问令牌和刷新令牌&quot;">​</a></h2><p>在配置好您的 OAuth 应用程序并创建好您的凭据 JSON 文件后，请按照以下步骤对 Langflow 应用程序进行身份验证。</p><ol><li>在 Langflow 中创建一个新项目。</li><li>将一个 <strong>Google OAuth Token</strong> 组件添加到您的流程中。</li><li>在 Google OAuth Token 组件的 <strong>Credentials File</strong> 字段中，输入您的 <strong>Credentials File</strong> 路径，即之前从 Google 下载的包含客户端 ID 凭据的 JSON 文件。</li><li>要对您的应用程序进行身份验证，请在 <strong>Google OAuth Token</strong> 组件中点击 <strong>播放</strong>。 浏览器中将打开一个新标签页，以使用您的 Google Cloud 账户对您的应用程序进行身份验证。您必须使用创建 OAuth 凭据的同一个 Google 账户对应用程序进行身份验证。</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>如果没有自动打开新标签页，请检查 Langflow 的 <strong>日志</strong> 中是否有 Google 认证 URL。 在浏览器中打开此 URL 以完成身份验证。</p></div><ol start="5"><li>认证成功后，您的 Langflow 应用程序现在可以请求和刷新令牌。这些令牌使 Langflow 能够代表您与 Google 服务进行交互并执行您指定的请求。</li></ol><h2 id="创建使用-google-drive-加载器的流程" tabindex="-1">创建使用 Google Drive 加载器的流程 <a class="header-anchor" href="#创建使用-google-drive-加载器的流程" aria-label="Permalink to &quot;创建使用 Google Drive 加载器的流程&quot;">​</a></h2><p>要获取一个使用 Google Drive 加载器组件的预构建 JSON 文件，请下载 <a href="./files/Google_Drive_Docs_Translations_Example.json">Google Drive 文档翻译示例流程 JSON</a> 到本地。</p><p>在此示例中，<strong>Google Drive 加载器</strong>组件加载托管在 Google Drive 上的文本文件，将文本翻译成西班牙语，并将其返回到聊天输出。</p><ol><li>下载 <a href="./files/Google_Drive_Docs_Translations_Example.json">Google Drive 文档翻译示例流程 JSON</a> 到本地。</li><li>要将下载的 JSON 导入到 Langflow 中，点击 <strong>选项</strong>，然后选择 <strong>导入</strong>。</li><li>在 Google OAuth Token 组件的 <strong>凭证文件</strong> 字段中，输入你从 Google 下载的包含客户端 ID 凭证的 JSON 文件的路径。</li><li>在 Google Drive 加载器组件中，在 <code>服务帐户令牌的 JSON 字符串</code> 字段中，输入 Google OAuth Token 组件输出中返回的令牌的 JSON 字符串。</li></ol><p>示例流程包括一个 <strong>解析数据</strong> 组件，用于将 Google OAuth Token 组件的 <code>data</code> 输出转换为 JSON 清理器组件的 <code>text</code> 输入。</p><ol start="5"><li>为使 Langflow 组件访问 Google Drive 中的文件，复制文档 URL 中的 Google Drive 文件 ID。</li></ol><blockquote><p><strong>信息</strong><br> 文件 ID 位于 Google Drive 文档 URL 的 <code>/d/</code> 和 <code>/edit</code> 之间。<br> 例如，在 URL <code>https://drive.google.com/file/d/1a2b3c4D5E6F7gHI8J9klmnopQ/edit</code> 中，文件 ID 是 <code>1a2b3c4D5E6F7gHI8J9klmnopQ</code>。</p></blockquote><ol start="6"><li>在 Google Drive 加载器组件中，在 <strong>Document ID</strong> 字段中粘贴文档 URL。</li><li>点击 <strong>聊天输出</strong> 组件，然后点击 <strong>播放</strong>。<br> 聊天输出应显示翻译后的文档。</li></ol>',22)]))}const G=e(n,[["render",s]]);export{f as __pageData,G as default};
